def solve_small_board(N):
    # ... (function definition copied from previous call)
    grid = [[i * N + j + 1 for j in range(N)] for i in range(N)]

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                neighbors.append((nr, nc))
        return neighbors

    S = []
    for r in range(N):
        for c in range(N):
            is_start = True
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] < grid[r][c]:
                    is_start = False
                    break
            if is_start:
                S.append((r, c))

    memo = {}

    def count_paths(r, c):
        if (r, c) in memo:
            return memo[(r, c)]

        count = 1
        current_value = grid[r][c]
        for nr, nc in get_neighbors(r, c):
            next_value = grid[nr][nc]
            if next_value > current_value:
                count += count_paths(nr, nc)

        memo[(r, c)] = count
        return count

    total_paths = 0
    for r, c in S:
        total_paths += count_paths(r, c)

    return grid, S, total_paths

